/* @lc app=leetcode id=3609 lang=kotlin */ class Solution { fun f(sx: Int, sy: Int, a: Long, b: Long): Int = if (a == sx.toLong() && b == sy.toLong()) 0 else if (a < sx || b < sy) 1_000_000 else (if (a > b) (if (2 * b <= a) (if (a % 2 == 0L) listOf(a / 2 to b) else listOf()) else listOf(a - b to b)) else if (b > a) (if (2 * a <= b) (if (b % 2 == 0L) listOf(a to b / 2) else listOf()) else listOf(a to b - a)) else (if (a == 0L) listOf() else listOf(0L to b, a to 0L))).map { (x, y) -> f(sx, sy, x, y) }.minOrNull()?.let { it + 1 } ?: 1_000_000 fun minMoves(sx: Int, sy: Int, tx: Int, ty: Int): Int = f(sx, sy, tx.toLong(), ty.toLong()).let { if (it >= 1_000_000) -1 else it } }